        "section_id": "key-findings-recommendations",
        "title": "Key Findings & Policy Implications",
        "objective": "Synthesize the most important insights from the analysis into actionable findings, including recommendations for policymakers on subsidy design, tax calibration, and price stabilization mechanisms."
      }
    ],
    "kpis": [
      {
        "name": "Average Retail Petrol Price (USD/Liter)",
        "description": "The mean petrol price across all countries and weeks, used as the primary benchmark for global fuel cost."
      },
      {
        "name": "Brent-to-Retail Price Correlation",
        "description": "Pearson correlation coefficient between weekly Brent Crude prices and retail petrol/diesel prices, measuring how tightly global benchmarks drive local costs."
      },
      {
        "name": "Subsidy Price Dampening Effect",
        "description": "The percentage difference in average retail fuel price between High-subsidy and Low-subsidy countries, quantifying the impact of government intervention."
      },
      {
        "name": "Regional Price Spread",
        "description": "The difference between the highest and lowest regional average petrol price in a given year, indicating global pricing inequality."
      },
      {
        "name": "Tax-to-Price Ratio by Income Level",
        "description": "Average tax percentage segmented by income level, revealing how fiscal policy on fuel varies with national wealth."
      }
    ],
    "analysis_dimensions": [
      "region",
      "income_level",
      "subsidy_level",
      "date",
      "tax_percentage"
    ]
  }
}

