  .badge-medium { background: #fef9e7; color: #9a6900; }
  .badge-neutral { background: #eaf0fb; color: #1a5276; }

  /* ── INSIGHT BOXES ── */
  .insight-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; }
  .insight-box {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
  }
  .insight-box h4 { font-size: 13px; font-weight: 700; color: var(--primary); margin-bottom: 8px; }
  .insight-box p { font-size: 13px; color: var(--muted); line-height: 1.55; }
  .insight-box .big-num { font-size: 28px; font-weight: 700; color: var(--accent); line-height: 1.1; margin-bottom: 4px; }

  /* ── FINDINGS ── */
  .finding {
    display: flex; gap: 16px;
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 12px;
  }
