  .finding-body p { font-size: 13px; color: var(--muted); }

  /* ── DISCLAIMER ── */
  .disclaimer {
    background: #eaf0fb;
    border-left: 4px solid var(--accent);
    border-radius: 4px;
    padding: 12px 16px;
    font-size: 12px;
    color: var(--muted);
    margin-bottom: 32px;
  }

  /* ── FOOTER ── */
  footer {
    text-align: center;
    padding: 24px;
    font-size: 12px;
    color: var(--muted);
    border-top: 1px solid var(--border);
